-- 009 飯田市オープンデータ「公共施設一覧」の公共施設を、市の CSV にそろえる。
-- このファイルは npm run public-facilities:sql で作る。手で編集しない（手順は docs/009_ingest-city-opendata.md）
-- CSV：https://www.city.iida.lg.jp/uploaded/attachment/76250.csv

update public.data_sources set
  credit_text = '出典：飯田市（https://www.city.iida.lg.jp/soshiki/168/opendata.html）、PDL1.0（https://www.digital.go.jp/resources/open_data/public_data_license_v1.0）（2026年10月26日に利用）。「公共施設一覧」（飯田市）（https://www.city.iida.lg.jp/soshiki/168/opendata.html）を加工して作成（暮らしに関係する施設を選び、種類を分けた）',
  period_label = '2025年6月23日更新',
  checked_on = '2026-10-26'::date
where id = 'iida_public_facilities';

delete from public.facilities where source_id = 'iida_public_facilities';
